"""Exports are generated by code and delivered by the authorized Telegram handler."""
from app.agent.report_scope import request_scope
from app.services.report_helpers import export_rows,csv_bytes


def remember(kind,arguments):
    state=request_scope.get()
    if state is not None: state['last_report']={'kind':kind,'arguments':arguments}


async def create():
    state=request_scope.get()
    saved=state.get('last_report') if state else None
    if not saved: raise ValueError('Сначала выберите отчёт и фильтры для выгрузки.')
    if len(state.get('attachments',[]))>=3: raise ValueError('Не более трёх файлов за ответ.')
    args=dict(saved['arguments'])
    args.pop('offset',None)
    current=state.get('point_id')
    if current is not None and ('' if current=='network' else str(current))!=str(args.get('point_id') or ''):
        raise ValueError('Область диалога изменилась. Сначала получите нужный отчёт для новой области.')
    if saved['kind']=='detail':
        from app.services.detail_reports import report
        data=await report(**args,export_all=True)
        rows=export_rows(data,args)
    elif saved['kind']=='advanced':
        from app.services.advanced_reports import report
        data=await report(**args,export_all=True)
        rows=[{**r,'filters':args,'basis':data.get('metadata',{}).get('basis'),
               'complete_source':False} for r in data.get('rows',[])]
    else: raise ValueError('Для этой выгрузки выберите детальный отчёт товаров, клиентов, средних чеков или аналитики.')
    content=csv_bytes(rows)
    if len(content)>45*1024*1024: raise ValueError('Сузьте период: файл больше 45 МБ.')
    filename=f"prichal-{args['kind']}.csv"
    state.setdefault('attachments',[]).append({'filename':filename,'content':content})
    return {'status':'FILE_READY','filename':filename,'rows':len(rows),'filters':args,
            'delivery':'Telegram sends the attachment after this answer. Not yet delivered.',
            'snapshot':'Re-read local data using the same filters; values may change since the earlier report.'}
